using System;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public static class ChartHover {
 public static int Index(double x,double left,double width,int count){if(count<=0||width<=0||x<left||x>left+width)return -1;return Math.Min(count-1,(int)((x-left)/width*count));}
 public static void Line(DrawingContext dc,double x,double top,double bottom,Brush brush){var pen=new Pen(brush,1){DashStyle=DashStyles.Dash};dc.DrawLine(pen,new Point(x,top),new Point(x,bottom));}
 public static void ResetMark(DrawingContext dc,double x,double y){var halo=new SolidColorBrush(Color.FromArgb(55,232,179,95));var border=new SolidColorBrush(Color.FromRgb(235,190,121));var center=new SolidColorBrush(Color.FromRgb(252,222,170));dc.DrawEllipse(halo,null,new Point(x,y),8,8);dc.DrawEllipse(new SolidColorBrush(Color.FromRgb(30,42,62)),new Pen(border,1.5),new Point(x,y),4.5,4.5);dc.DrawEllipse(center,null,new Point(x,y),1.8,1.8);}
 public static void Background(DrawingContext dc,double width,double height){if(width>0&&height>0)dc.DrawRoundedRectangle(new SolidColorBrush(Color.FromArgb(35,63,103,160)),null,new Rect(0,0,width,height),10,10);}
 public static void Show(DrawingContext dc,FrameworkElement chart,double x,double y,double left,double right,double top,double bottom,string text){if(String.IsNullOrEmpty(text))return;var accent=new SolidColorBrush(Color.FromRgb(126,192,255));Line(dc,x,top,bottom,accent);y=Math.Max(top,Math.Min(bottom,y));var guide=new Pen(accent,.8){DashStyle=DashStyles.Dash};dc.DrawLine(guide,new Point(left,y),new Point(right,y));dc.DrawEllipse(accent,new Pen(Brushes.White,1),new Point(x,y),3,3);
  var formatted=new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),12,Brushes.White,VisualTreeHelper.GetDpi(chart).PixelsPerDip){MaxTextWidth=260,MaxTextHeight=Math.Max(30,chart.ActualHeight-24),Trimming=TextTrimming.CharacterEllipsis};double w=formatted.Width+24,h=formatted.Height+18;double visibleLeft=0,visibleRight=chart.ActualWidth;DependencyObject node=chart;while((node=VisualTreeHelper.GetParent(node))!=null){var viewer=node as ScrollViewer;if(viewer!=null){visibleLeft=viewer.HorizontalOffset;visibleRight=visibleLeft+viewer.ViewportWidth;break;}}double px=x+14;if(px+w>visibleRight-4)px=x-w-14;px=Math.Max(visibleLeft+4,Math.Min(px,visibleRight-w-4));double py=Math.Max(4,Math.Min(y+12,chart.ActualHeight-h-4));dc.DrawRoundedRectangle(new SolidColorBrush(Color.FromArgb(245,18,31,52)),new Pen(new SolidColorBrush(Color.FromRgb(89,132,184)),1),new Rect(px,py,w,h),8,8);dc.DrawText(formatted,new Point(px+12,py+9));
 }
}
